from pathlib import Path
import json
p=Path('docs/codex-queue/244/prompts.json');jobs=json.loads(p.read_text())
if len(jobs)!=16: raise SystemExit('Giữ prompt hiện có; không thêm lại các lượt đã sinh.')
fixes={12:'Correction for final attempt 3: Increase readability and average brightness at 24 pixels. The front-facing square key has a SMALL plain dark iron centre covering just ONE THIRD of its face area; the rest of the face is a very broad bright hammered GOLD BEVEL. The key still has its obvious front skirt and two small curved ember-gold sound arcs at the right. The bright material carries the majority of the silhouette. Keep the required dark outline, but use large bright gold planes inside it. At tiny size, the subject reads as a keyboard key broadcasting two curved sound waves.',1:'Correction for attempt 2: Increase readability and average brightness at 24 pixels. Make the speech bubble rim VERY THICK and BRIGHT hammered gold with pale gold highlights. The plain dark centre occupies just ONE THIRD of the bubble face area, leaving two thirds as a broad bright solid gold body. The unmistakable POINTED TAIL projects well below-left. Keep two thick short sound crescents to the right. The bright gold body is dominant, with only one plain dark interior recess. One compact speech-bubble silhouette; broad planes, quiet grain.',6:'Correction for attempt 2: Simplify the key and distinguish the silhouette from the sound-arcs icon. The LEFT key is a SMALL square mechanical keycap with a plain jade face and simple gold bevel, only 40 percent of the entire width. The RIGHT half is three distinctly spaced STRAIGHT gold volume bars, rising from a short first bar to a TALL third bar that is taller than the key. Align their bottoms. The visual silhouette is a SMALL KEY beside THREE LARGE ASCENDING RECTANGLES. Keep key faces plain jade and bar faces plain polished gold; texture is faint and vanishes at 24 pixels.'}
for i,fix in fixes.items():
 j=jobs[i].copy();j['attempt']=3 if i==12 else 2;j['output']=j['output'].replace('try2','try3') if i==12 else j['output'].replace('try1','try2');j['prompt']+='\n'+fix+'\n';jobs.append(j)
for i in [8,9,10,11]:
 j=jobs[i].copy();j['attempt']=2;j['output']=j['output'].replace('try1','try2');j['prompt']+='\nCorrection for attempt 2: The previous output changed the physical aspect ratio, which failed alpha registration. Preserve a STRICTLY 16:1 OUTER SILHOUETTE, exactly sixteen times as wide as high, matching the attached edit target. For an example width of 2048 pixels, the complete outer hardware height is EXACTLY 128 pixels, including all rims and caps. At width 2176 pixels, the full hardware height is EXACTLY 136 pixels. Both caps occupy the exact same coordinates relative to the hardware as in the target. The rail touches neither canvas edge. Leave clear transparent margins around the complete hardware. Maintain the target’s outline with high precision; change only the channel material as requested. The entire channel, rims and caps have a clean opaque alpha silhouette. All lighting and grain is confined inside the hardware.\n';jobs.append(j)
p.write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
